Here is the commit message:
bpf: Fix stack-out-of-bounds write in devmap
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

get_upper_ifindexes() iterates over all upper devices and writes their
indices into an array without checking bounds.

Also the callers assume that the max number of upper devices is
MAX_NEST_DEV and allocate excluded_devices[1+MAX_NEST_DEV] on the stack,
but that assumption is not correct and the number of upper devices could
be larger than MAX_NEST_DEV (e.g., many macvlans), causing a
stack-out-of-bounds write.

Add a max parameter to get_upper_ifindexes() to avoid the issue.
When there are too many upper devices, return -EOVERFLOW and abort the
redirect.

To reproduce, create more than MAX_NEST_DEV(8) macvlans on a device with
an XDP program attached using BPF_F_BROADCAST | BPF_F_EXCLUDE_INGRESS.
Then send a packet to the device to trigger the XDP redirect path.

Reported-by: syzbot+10cc7f13760b31bd2e61@syzkaller.appspotmail.com
Closes: https://lore.kernel.org/all/698c4ce3.050a0220.340abe.000b.GAE@google.com/T/
Fixes: aeea1b86f936 ("bpf, devmap: Exclude XDP broadcast to master device")
Reviewed-by: Toke Høiland-Jørgensen <toke@redhat.com>
Signed-off-by: Kohei Enju <kohei@enjuk.jp>
Link: https://lore.kernel.org/r/20260225053506.4738-1-kohei@enjuk.jp
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

Here is the root cause:
The function `get_upper_ifindexes()` iterates over all upper devices without any bounds check, writing their ifindexes into a stack-allocated array `excluded_devices[1+MAX_NEST_DEV]`. Callers assume the number of upper devices is at most `MAX_NEST_DEV`, but this assumption is incorrect (e.g., many macvlans can exceed that limit), leading to a stack-out-of-bounds write.

Here is the patch:

 /* Get ifindex of each upper device. 'indexes' must be able to hold at
- * least MAX_NEST_DEV elements.
- * Returns the number of ifindexes added.
+ * least 'max' elements.
+ * Returns the number of ifindexes added, or -EOVERFLOW if there are too
+ * many upper devices.
  */
-static int get_upper_ifindexes(struct net_device *dev, int *indexes)
+static int get_upper_ifindexes(struct net_device *dev, int *indexes, int max)
 {
 	struct net_device *upper;
 	struct list_head *iter;
 	int n = 0;

 	netdev_for_each_upper_dev_rcu(dev, upper, iter) {
+		if (n >= max)
+			return -EOVERFLOW;
 		indexes[n++] = upper->ifindex;
 	}
+
 	return n;
 }

 int dev_map_enqueue_multi(struct xdp_frame *xdpf, struct net_device *dev_rx,
 			  struct bpf_map *map, bool exclude_ingress)
 {
 	struct bpf_dtab *dtab = container_of(map, struct bpf_dtab, map);
 	struct bpf_dtab_netdev *dst, *last_dst = NULL;
 	int excluded_devices[1+MAX_NEST_DEV];
 	struct hlist_head *head;
 	int num_excluded = 0;
 	unsigned int i;
 	int err;

 	if (exclude_ingress) {
-		num_excluded = get_upper_ifindexes(dev_rx, excluded_devices);
+		num_excluded = get_upper_ifindexes(dev_rx, excluded_devices,
+						   ARRAY_SIZE(excluded_devices) - 1);
+		if (num_excluded < 0)
+			return num_excluded;
+
 		excluded_devices[num_excluded++] = dev_rx->ifindex;
 	}

 	if (map->map_type == BPF_MAP_TYPE_DEVMAP) {
 		for (i = 0; i < map->max_entries; i++) {
 			dst = rcu_dereference_check(dtab->netdev_map[i],
 						    rcu_read_lock_bh_held());
 			if (!is_valid_dst(dst, xdpf))
 				continue;

 			if (is_ifindex_excluded(excluded_devices, num_excluded, dst->dev->ifindex))
 				continue;

 			/* we only need n-1 clones; last_dst enqueued below */
 			if (!last_dst) {
 				last_dst = dst;
 				continue;
 			}

 			err = dev_map_enqueue_clone(last_dst, dev_rx, xdpf);
 			if (err)
 				return err;

 			last_dst = dst;
 		}
 	} else { /* BPF_MAP_TYPE_DEVMAP_HASH */
 		for (i = 0; i < dtab->n_buckets; i++) {
 			head = dev_map_index_hash(dtab, i);
 			hlist_for_each_entry_rcu(dst, head, index_hlist,
 						 lockdep_is_held(&dtab->index_lock)) {
 				if (!is_valid_dst(dst, xdpf))
 					continue;

 				if (is_ifindex_excluded(excluded_devices, num_excluded,
 							dst->dev->ifindex))
 					continue;

 				/* we only need n-1 clones; last_dst enqueued below */
 				if (!last_dst) {
 					last_dst = dst;
 					continue;
 				}

 				err = dev_map_enqueue_clone(last_dst, dev_rx, xdpf);
 				if (err)
 					return err;

 				last_dst = dst;
 			}
 		}
 	}

 	/* consume the last copy of the frame */
 	if (last_dst)
 		bq_enqueue(last_dst->dev, xdpf, dev_rx, last_dst->xdp_prog);
 	else
 		xdp_return_frame_rx_napi(xdpf); /* dtab is empty */

 	return 0;
 }


 int dev_map_redirect_multi(struct net_device *dev, struct sk_buff *skb,
 			   const struct bpf_prog *xdp_prog,
 			   struct bpf_map *map, bool exclude_ingress)
 {
 	struct bpf_dtab *dtab = container_of(map, struct bpf_dtab, map);
 	struct bpf_dtab_netdev *dst, *last_dst = NULL;
 	int excluded_devices[1+MAX_NEST_DEV];
 	struct hlist_head *head;
 	struct hlist_node *next;
 	int num_excluded = 0;
 	unsigned int i;
 	int err;

 	if (exclude_ingress) {
-		num_excluded = get_upper_ifindexes(dev, excluded_devices);
+		num_excluded = get_upper_ifindexes(dev, excluded_devices,
+						   ARRAY_SIZE(excluded_devices) - 1);
+		if (num_excluded < 0)
+			return num_excluded;
+
 		excluded_devices[num_excluded++] = dev->ifindex;
 	}

 	if (map->map_type == BPF_MAP_TYPE_DEVMAP) {
 		for (i = 0; i < map->max_entries; i++) {
 			dst = rcu_dereference_check(dtab->netdev_map[i],
 						    rcu_read_lock_bh_held());
 			if (!dst)
 				continue;

 			if (is_ifindex_excluded(excluded_devices, num_excluded, dst->dev->ifindex))
 				continue;

 			/* we only need n-1 clones; last_dst enqueued below */
 			if (!last_dst) {
 				last_dst = dst;
 				continue;
 			}

 			err = dev_map_redirect_clone(last_dst, skb, xdp_prog);
 			if (err)
 				return err;

 			last_dst = dst;

 		}
 	} else { /* BPF_MAP_TYPE_DEVMAP_HASH */
 		for (i = 0; i < dtab->n_buckets; i++) {
 			head = dev_map_index_hash(dtab, i);
 			hlist_for_each_entry_safe(dst, next, head, index_hlist) {
 				if (is_ifindex_excluded(excluded_devices, num_excluded,
 							dst->dev->ifindex))
 					continue;

 				/* we only need n-1 clones; last_dst enqueued below */
 				if (!last_dst) {
 					last_dst = dst;
 					continue;
 				}

 				err = dev_map_redirect_clone(last_dst, skb, xdp_prog);
 				if (err)
 					return err;

 				last_dst = dst;
 			}
 		}
 	}

 	/* consume the first skb and return */
 	if (last_dst)
 		return dev_map_generic_redirect(last_dst, skb, xdp_prog);

 	/* dtab is empty */
 	consume_skb(skb);
 	return 0;
 }



